+
+void main() async {
+  const projectId = ''; // Enter your projectId here.
+  if (projectId.isEmpty) {
+    print('Please provide a project ID in the `projectId` constant.');
+    return;
+  }
+
+  // Connects to the Cloud DNS API using Application Default Credentials (ADC).
+  //
+  // Before running this example, you need to authenticate with gcloud:
+  //
+  // ```
+  // $ gcloud auth application-default login
+  // ```
+  //
+  // See https://cloud.google.com/docs/authentication/application-default-credentials
+  final client = await auth.clientViaApplicationDefaultCredentials(
+    scopes: ['https://www.googleapis.com/auth/cloud-platform'],
+  );
+  final managedZonesService = managedZones(client: client);
+
+  try {
+    final response = await managedZonesService.list(
+      ManagedZones_ListRequest(project: projectId),
+    );
+
+    print('Managed zones in project $projectId:');
+    if (response.managedZones.isEmpty) {
+      print('  (none)');
+    } else {
+      for (final zone in response.managedZones) {
+        print('  - ${zone.name} (${zone.dnsName})');
+      }
+    }
+  } finally {
+    managedZonesService.close();
+  }
+}

